package glitch

import data.glitch_lib

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Find ConditionalStatement nodes (switch/case/if structures)
    conditions := glitch_lib.all_conditional_statements(parent)
    cond := conditions[_]

    # Check if it's a SWITCH or IF type conditional
    cond.type == "SWITCH"

    # For SWITCH statements, check if there's no default case
    # A default case is identified by is_default == true or condition being Null
    not has_default_case(cond)

    result := {
        "type": "sec_no_default_switch",
        "element": cond,
        "path": parent.path,
        "description": "Missing default case in conditional statement - All possible input values should be handled with a fallback or default case. (CWE-478)"
    }
}

# Helper rule to check if a conditional statement has a default case
has_default_case(cond) {
    cond.is_default == true
} else {
    cond.condition.ir_type == "Null"
} else {
    # Check if any else_statement chain has a default case
    has_default_case_in_chain(cond.else_statement)
}

has_default_case_in_chain(statement) {
    statement.is_default == true
} else {
    statement.condition.ir_type == "Null"
} else {
    statement.else_statement != null
    has_default_case_in_chain(statement.else_statement)
}

# Additional rule to detect missing fallback in Hash/Map lookups
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Find all Hash nodes that could be used for mapping/lookup
    walk(parent, [path, node])
    node.ir_type == "Hash"

    # Check if this hash is used in a context that requires a default
    # (e.g., assigned to a variable that's later used in conditionals)
    # For now, detect standalone hashes without default key
    not has_default_key(node)

    result := {
        "type": "sec_no_default_switch",
        "element": node,
        "path": parent.path,
        "description": "Missing default key in mapping structure - Maps used for conditional logic should include a default/fallback key. (CWE-478)"
    }
}

# Helper to check if a hash has a default key
has_default_key(hash_node) {
    # Check for explicit default key
    key := hash_node.value[_]
    key.ir_type == "String"
    regex.match("(?i)default|fallback|_", key.value)
} else {
    # Check for wildcard key
    key := hash_node.value[_]
    key.ir_type == "String"
    key.value == "*"
}
